import React, { useEffect, useState } from "react";
import API_BASE_URL from "../config";
import "../styles/UserPages.css";

const MessageInbox = () => {
  const userId = sessionStorage.getItem("userId");
  const [partners, setPartners] = useState([]);
  const [selectedUser, setSelectedUser] = useState(null);
  const [messages, setMessages] = useState([]);
  const [text, setText] = useState("");

  useEffect(() => {
    fetch(`${API_BASE_URL}/api/messages/partners/${userId}`)
      .then(res => res.json())
      .then(data => setPartners(data));
  }, [userId]);

  const loadChat = async (partnerId) => {
    setSelectedUser(partnerId);
    const res = await fetch(`${API_BASE_URL}/api/messages/${userId}/${partnerId}`);
    const data = await res.json();
    setMessages(data);
  };

  const sendMessage = async () => {
    if (!text.trim()) return;

    await fetch(`${API_BASE_URL}/api/messages`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        sender_id: userId,
        receiver_id: selectedUser,
        message: text
      }),
    });

    setText("");
    loadChat(selectedUser); // reload chat
  };

  return (
    <div className="message-inbox-container">
      <div className="inbox-sidebar">
        <h3>Chats</h3>
        {partners.map((p) => (
          <button
            key={p.partner_id}
            onClick={() => loadChat(p.partner_id)}
            className={p.partner_id === selectedUser ? "active-chat" : ""}
          >
            {p.name || `User ${p.partner_id}`}
          </button>
        ))}
      </div>

      <div className="inbox-chat-area">
        {selectedUser ? (
          <>
            <div className="messages">
              {messages.map((msg) => (
                <div
                  key={msg.id}
                  className={msg.sender_id == userId ? "sent" : "received"}
                >
                  <p>{msg.message}</p>
                  <span>{new Date(msg.timestamp).toLocaleTimeString()}</span>
                </div>
              ))}
            </div>
            <div className="chat-input-area">
              <input
                value={text}
                onChange={(e) => setText(e.target.value)}
                placeholder="Type a message..."
              />
              <button onClick={sendMessage}>Send</button>
            </div>
          </>
        ) : (
          <p>Select a user to chat with</p>
        )}
      </div>
    </div>
  );
};

export default MessageInbox;
